-- Frozen unversioned store from 444b999; synthetic test keys.
BEGIN TRANSACTION;
CREATE TABLE manifests(
    log_id TEXT PRIMARY KEY,
    manifest_hash TEXT NOT NULL UNIQUE,
    envelope BLOB NOT NULL
);
INSERT INTO "manifests" VALUES('123e4567-e89b-42d3-a456-426614174000','19bf8e0c623a772a103dd7a4deaaa38bb6f9ea0c8ce99504900117cb376cf768',X'');
CREATE TABLE w_checkpoints(
    log_id TEXT NOT NULL,
    idx INTEGER NOT NULL,
    checkpoint_hash TEXT NOT NULL,
    envelope BLOB NOT NULL,
    UNIQUE(log_id, idx),
    UNIQUE(log_id, checkpoint_hash)
);
INSERT INTO "w_checkpoints" VALUES('123e4567-e89b-42d3-a456-426614174000',0,'47c8a4e6e723a0d40a049d4f6369140c04381bbd4869d9b4ba15b96153abe407',X'');
INSERT INTO "w_checkpoints" VALUES('123e4567-e89b-42d3-a456-426614174000',1,'00d2bcdbb98089557ec62fc302535ad5eee0d11ef7e0b1d3a7b0603e5e3ba83e',X'');
CREATE TABLE w_receipts(
    checkpoint_hash TEXT PRIMARY KEY,
    envelope BLOB NOT NULL
);
INSERT INTO "w_receipts" VALUES('47c8a4e6e723a0d40a049d4f6369140c04381bbd4869d9b4ba15b96153abe407',X'');
INSERT INTO "w_receipts" VALUES('00d2bcdbb98089557ec62fc302535ad5eee0d11ef7e0b1d3a7b0603e5e3ba83e',X'');
CREATE TABLE w_record_digests(
    log_id TEXT NOT NULL,
    seq INTEGER NOT NULL,
    record_hash TEXT NOT NULL,
    UNIQUE(log_id, seq)
);
INSERT INTO "w_record_digests" VALUES('123e4567-e89b-42d3-a456-426614174000',1,'5fd710c2dd01d5d4fbd6f1c5bed583795e86befd38024a3a63ed181169e3fcbe');
INSERT INTO "w_record_digests" VALUES('123e4567-e89b-42d3-a456-426614174000',2,'bd453dd7c9155233bfdcccbeacdf17e456a9e7e47dce8317ae9a044da133dcf1');
CREATE TABLE w_state(
    log_id TEXT PRIMARY KEY,
    count INTEGER NOT NULL,
    head_hash TEXT NOT NULL,
    checkpoint_index INTEGER NOT NULL,
    checkpoint_hash TEXT NOT NULL,
    receipt_hash TEXT NOT NULL,
    sealed INTEGER NOT NULL DEFAULT 0
);
INSERT INTO "w_state" VALUES('123e4567-e89b-42d3-a456-426614174000',2,'bd453dd7c9155233bfdcccbeacdf17e456a9e7e47dce8317ae9a044da133dcf1',1,'00d2bcdbb98089557ec62fc302535ad5eee0d11ef7e0b1d3a7b0603e5e3ba83e','d93576108ba1346ee1ee22729a3a7d918ed6e28493ed008908cbfe157a0bc2f2',1);
CREATE TABLE w_status(
    manifest_hash TEXT PRIMARY KEY,
    serial INTEGER NOT NULL CHECK(serial >= 1),
    status TEXT NOT NULL CHECK(status IN ('active', 'revoked'))
);
INSERT INTO "w_status" VALUES('19bf8e0c623a772a103dd7a4deaaa38bb6f9ea0c8ce99504900117cb376cf768',1,'active');
CREATE TRIGGER w_checkpoints_no_update
BEFORE UPDATE ON w_checkpoints
BEGIN SELECT RAISE(ABORT, 'checkpoints are append only'); END;
CREATE TRIGGER w_checkpoints_no_delete
BEFORE DELETE ON w_checkpoints
BEGIN SELECT RAISE(ABORT, 'checkpoints are append only'); END;
CREATE TRIGGER w_receipts_no_update
BEFORE UPDATE ON w_receipts
BEGIN SELECT RAISE(ABORT, 'receipts are immutable'); END;
CREATE TRIGGER w_receipts_no_delete
BEFORE DELETE ON w_receipts
BEGIN SELECT RAISE(ABORT, 'receipts are immutable'); END;
CREATE TRIGGER w_digests_no_update
BEFORE UPDATE ON w_record_digests
BEGIN SELECT RAISE(ABORT, 'record digests are append only'); END;
CREATE TRIGGER w_digests_no_delete
BEFORE DELETE ON w_record_digests
BEGIN SELECT RAISE(ABORT, 'record digests are append only'); END;
CREATE TRIGGER w_manifests_no_update
BEFORE UPDATE ON manifests
BEGIN SELECT RAISE(ABORT, 'manifests are immutable'); END;
CREATE TRIGGER w_manifests_no_delete
BEFORE DELETE ON manifests
BEGIN SELECT RAISE(ABORT, 'manifests are immutable'); END;
COMMIT;
